1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
10	import { capacityCheck, diskCapacityCheck } from "./capacity";
11	import { invoiceCreateData } from "./invoices";
12	import { maybeRewardReferral } from "./actions-growth";
13	import { currentPromo, promoPriceCents } from "./promotions";
14	import { extraDiskPerGbCents } from "./disk-expand";
15	import {
16	  EXTRA_DISK_MAX_ADD_GB,
17	  EXTRA_DISK_MAX_TOTAL_GB,
18	  effectiveDiskGB,
19	  extraDiskCentsAt,
20	  extraDiskLabel,
21	  normalizeExtraDiskGB,
22	} from "./extra-disk";
23	
24	export class OrderError extends Error {}
25	
26	export const orderSchema = z.object({
27	  planId: z.string().min(1),
28	  osTemplateId: z.string().min(1),
29	  hostname: z
30	    .string()
31	    .min(3)
32	    .max(40)
33	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
34	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
35	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
36	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
37	});
38	
39	export type OrderIntent = {
40	  planId: string;
41	  osTemplateId: string;
42	  hostname: string;
43	  nodeId?: string;
44	  addonMalware?: boolean;
45	  addonBackup?: boolean;
46	  addonDocker?: boolean;
47	  termMonths?: number;
48	  dedicatedIp?: boolean;
49	  sshPublicKey?: string;
50	  sshKeyName?: string;
51	  free?: boolean;
52	  /**
53	   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
54	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
55	   * post-deploy expansion job is needed. Permanent — never shrinks.
56	   */
57	  extraDiskGB?: number;
58	};
59	
60	/**
61	 * The price an order was SOLD at: the total, and the promo rate that produced it.
62	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
63	 *
64	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
65	 * path quoted a total, charged the CARD its share of that total at Stripe, and
66	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
67	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
68	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
69	 * so a rotation between "customer clicked Deploy" and "customer came back from
70	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
71	 * out of the wallet with no new consent. With no balance to take it from, the
72	 * payment was captured and no server was created.
73	 *
74	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
75	 * Stripe metadata for exactly this reason; the order path was the one that
76	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
77	 * the customer was shown is not recomputed later, it is carried.
78	 *
79	 * `promoPercent` and `promoName` travel WITH the total because they are not
80	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
81	 * at (every later proration prices against it), and the promo name is the ledger
82	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
83	 * today's 15% would hand every later proration the wrong basis and print a
84	 * discount on the invoice that does not match the money taken.
85	 */
86	export type OrderPrice = {
87	  /** Total to charge, in cents — the figure the customer consented to. */
88	  chargeCents: number;
89	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
90	  promoPercent: number;
91	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
92	  promoName: string;
93	};
94	
95	/** The sold price implied by a quote — the ONE place a quote becomes a price. */
96	export function orderPriceOf(quote: {
97	  chargeCents: number;
98	  promo: { discountPercent: number; name: string };
99	}): OrderPrice {
100	  return {
101	    chargeCents: quote.chargeCents,
102	    promoPercent: quote.promo.discountPercent,
103	    promoName: quote.promo.name,
104	  };
105	}
106	
107	/**
108	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
109	 * well-formed: a half-parsed price would be worse than no price at all, because
110	 * the caller's fallback (re-quote) is at least internally consistent.
111	 */
112	export function parseOrderPrice(raw: unknown): OrderPrice | null {
113	  let obj: unknown = raw;
114	  if (typeof raw === "string") {
115	    try {
116	      obj = JSON.parse(raw);
117	    } catch {
118	      return null;
119	    }
120	  }
121	  if (!obj || typeof obj !== "object") return null;
122	  const { chargeCents, promoPercent, promoName } = obj as Record<string, unknown>;
123	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
124	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
125	  if (promoPercent < 0 || promoPercent > 100) return null;
126	  return { chargeCents, promoPercent, promoName: typeof promoName === "string" ? promoName : "" };
127	}
128	
129	/** Extract a plain OrderIntent from a deploy form. */
130	export function intentFromFormData(formData: FormData): OrderIntent {
131	  return {
132	    planId: String(formData.get("planId") ?? ""),
133	    osTemplateId: String(formData.get("osTemplateId") ?? ""),
134	    hostname: String(formData.get("hostname") ?? ""),
135	    nodeId: String(formData.get("nodeId") ?? "") || undefined,
136	    addonMalware: formData.get("addon_malware") === "1",
137	    addonBackup: formData.get("addon_backup") === "1",
138	    addonDocker: formData.get("addon_docker") === "1",
139	    termMonths: Number(formData.get("termMonths") ?? 1),
140	    dedicatedIp: formData.get("dedicatedIp") === "1",
141	    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
142	    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
143	    free: formData.get("free") === "1",
144	    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
145	    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
146	    // bought so it drops out of JSON.stringify: the intent is round-tripped
147	    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
148	    // createOrderCheckout), and every byte of headroom matters there.
149	    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
150	  };
151	}
152	
153	/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
154	async function scheduleNode(planRamMB: number) {
155	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
156	  if (nodes.length === 0) return null;
157	  const loads = await Promise.all(
158	    nodes.map(async (n) => {
159	      const agg = await db.server.findMany({
160	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
161	        select: { plan: { select: { ramMB: true } } },
162	      });
163	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
164	      return { node: n, free: n.capacityRamMB - used };
165	    }),
166	  );
167	  loads.sort((a, b) => b.free - a.free);
168	  return loads[0].node;
169	}
170	
171	/** Validate + price an order without placing it. Throws OrderError on any problem. */
172	export async function orderQuote(intent: OrderIntent) {
173	  const parsed = orderSchema.safeParse(intent);
174	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
175	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
176	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
177	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
178	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
179	    throw new OrderError(
180	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
181	    );
182	  }
183	  const term = vpsTerm(Number(intent.termMonths ?? 1));
184	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
185	
186	  // Extra root disk, priced per GB/month and multiplied over the term exactly
187	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
188	  // promo — the customer pays the same $/GB whichever term they pick, and renews
189	  // at the same rate). Growth is one-way: this is permanent for the server.
190	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
191	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
192	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
193	  const extraDiskCents = extraDiskMonthlyCents * term.months;
194	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
195	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
196	  }
197	
198	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
199	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
200	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
201	  // real renewal price and this discounted value is the real first-term price.
202	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
203	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
204	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
205	  const promo = currentPromo(new Date());
206	  const planFirstTermCents = promoPriceCents(regularPlanCents, promo);
207	  const chargeCents = planFirstTermCents + ipCents + extraDiskCents;
208	  return {
209	    plan,
210	    os,
211	    term,
212	    chargeCents,
213	    promo,
214	    regularPlanCents,
215	    extraDiskGB,
216	    extraDiskMonthlyCents,
217	    extraDiskCents,
218	  };
219	}
220	
221	/**
222	 * Place an order: validate, charge the wallet (unless a free admin grant),
223	 * create the Server + PROVISION job. Returns the new server id. Does NOT
224	 * redirect. Callers must ensure funds exist (or pass free) — this still
225	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
226	 *
227	 * `sold` overrides the recomputed price with the one the order was actually SOLD
228	 * at — the card-paid path passes the figure stamped on the Checkout session
229	 * BEFORE the card was charged, so the confirm redirect settles the price the
230	 * customer consented to instead of re-pricing against whatever promo is running
231	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
232	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
233	 * quote, which it computed moments ago in the same request. See OrderPrice.
234	 */
235	export async function placeOrder(
236	  user: User,
237	  intent: OrderIntent,
238	  sold?: OrderPrice | null,
239	): Promise<string> {
240	  const quote = await orderQuote(intent);
241	  const { plan, os, term, promo, extraDiskGB, extraDiskMonthlyCents, extraDiskCents } = quote;
242	  // Everything below bills off THESE three, never off `quote.chargeCents` /
243	  // `promo` directly: when a sold price is present it is the whole truth about
244	  // what this order costs and what rate it was sold at.
245	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
246	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
247	  const promoName = sold?.promoName || promo.name;
248	  // Note the intro discount on the billing document (first term only; renews full).
249	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
250	
251	  const cap = await capacityCheck(plan.id);
252	  if (!cap.ok) throw new OrderError(cap.reason);
253	
254	  let nodeId: string | null = null;
255	  if (intent.nodeId) {
256	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
257	    if (!n) throw new OrderError("Selected location is not available.");
258	    nodeId = n.id;
259	  } else {
260	    const n = await scheduleNode(plan.ramMB);
261	    nodeId = n?.id ?? null;
262	  }
263	
264	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
265	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
266	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
267	
268	  const addons = {
269	    malwareScanner: !!intent.addonMalware,
270	    dailyBackup: !!intent.addonBackup,
271	    docker: !!intent.addonDocker,
272	  };
273	  const isAdmin = user.role === "ADMIN";
274	  const freeRequested = !!intent.free && isAdmin;
275	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
276	
277	  const newKey = (intent.sshPublicKey ?? "").trim();
278	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
279	
280	  let server;
281	  try {
282	    server = await db.$transaction(async (tx) => {
283	      if (!freeRequested) {
284	        await debitWallet(tx, user.id, chargeCents);
285	        await tx.walletTransaction.create({
286	          data: {
287	            userId: user.id,
288	            amountCents: -chargeCents,
289	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`,
290	          },
291	        });
292	        // Billing document for the charge — created inside the same debit tx so it
293	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
294	        // Extra disk gets its OWN line so the customer can see exactly what the
295	        // permanent storage costs; the lines always sum back to chargeCents.
296	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`;
297	        const planLineCents = chargeCents - extraDiskCents;
298	        await tx.invoice.create({
299	          data: invoiceCreateData({
300	            userId: user.id,
301	            description: lineDesc,
302	            status: "PAID",
303	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
304	            lineItems: [
305	              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
306	              ...(extraDiskCents > 0
307	                ? [
308	                    {
309	                      description:
310	                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
311	                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
312	                      qty: 1,
313	                      unitCents: extraDiskCents,
314	                      amountCents: extraDiskCents,
315	                    },
316	                  ]
317	                : []),
318	            ],
319	          }),
320	        });
321	      }
322	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
323	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
324	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
325	      }
326	      const s = await tx.server.create({
327	        data: {
328	          name: intent.hostname,
329	          hostname: intent.hostname,
330	          userId: user.id,
331	          planId: plan.id,
332	          osTemplateId: os.id,
333	          nodeId,
334	          addons,
335	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
336	          // storage for easy restore") and re-confirms it on the Review step, but
337	          // `addons.dailyBackup` was write-only: the worker declares the key and
338	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
339	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
340	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
341	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
342	          // job was ever enqueued. A customer would discover the safety net they
343	          // were promised did not exist at the moment they needed it. Bridge it
344	          // here, at the point of sale.
345	          autoBackup: !!intent.addonBackup,
346	          backupIntervalHours: intent.addonBackup ? 24 : null,
347	          termMonths: term.months,
348	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
349	          // later proration prices the plan delta against this number instead of
350	          // whatever promo happens to be running when the customer clicks resize
351	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
352	          // half of a round trip by choosing the date, and pockets the spread.
353	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
354	          // this scalar and the cash collected describe the same transaction.
355	          // A free admin grant recorded as 100: nothing was paid for these months,
356	          // so nothing may ever prorate out of them.
357	          //
358	          // `promoPercent` — not `promo.discountPercent` — because a card-paid
359	          // order settles the rate it was SOLD at (see OrderPrice), which may no
360	          // longer be the promo running now. Recording today's rate against a
361	          // price collected under a different one is exactly the drift this
362	          // column exists to prevent.
363	          termPromoPercent: freeRequested ? 100 : promoPercent,
364	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
365	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
366	          // born at its full size, with no separate expansion job.
367	          extraDiskGB,
368	          wantsDedicatedIp: !!intent.dedicatedIp,
369	          isFree: freeRequested,
370	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
371	        },
372	      });
373	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
374	      return s;
375	    });
376	  } catch (e) {
377	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
378	    throw e;
379	  }
380	
381	  await db.auditLog.create({
382	    data: {
383	      userId: user.id,
384	      action: "server.order",
385	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
386	    },
387	  });
388	  if (!freeRequested) {
389	    try {
390	      await maybeRewardReferral(user.id);
391	    } catch {
392	      /* non-fatal */
393	    }
394	  }
395	  return server.id;
396	}
