15	  // The active intro promo (Summer Sale etc.). payAndDeploy charges the promo
16	  // price on the first term (lib/order.ts), so the wizard must DISPLAY it too —
17	  // otherwise displayed ($8.99) ≠ charged ($6.29). Computed server-side so the
18	  // shown promo matches the one checkout applies.
19	  const promo = currentPromo(new Date());
20	  const [plans, images, sshKeys, nodes, capacity, freeIps, defaultPlanSlug, defaultTerm] =
21	    await Promise.all([
22	      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
23	      db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
24	      db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true, publicKey: true } }),
25	      db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, publicIp: true } }),
26	      capacitySnapshot(),
27	      db.dedicatedIp.count({ where: { status: "FREE" } }),
28	      // Settings → Provisioning, "Default plan". Stored as a slug; resolved to an id
29	      // below because the wizard selects by id.
30	      getSetting("default_plan_slug", ""),
31	      // Settings → Billing, "Default billing term", in months and pre-validated against
32	      // VPS_TERMS.
33	      defaultTermMonths(),
34	    ]);
35	
36	  // Resolve slug → id HERE, against the same `plans` array handed to the wizard, so the
37	  // pre-selection can only ever name a plan the customer can actually see and buy. A
38	  // slug that no longer resolves (plan renamed, or deactivated since an operator chose
39	  // it) yields `undefined` and the wizard keeps its "first plan by sortOrder" default —
40	  // the panel's promise degrades to the old behaviour instead of pre-selecting nothing.
41	  const defaultPlanId = defaultPlanSlug
42	    ? plans.find((p) => p.slug === defaultPlanSlug)?.id
43	    : undefined;
