60	        <DeployWizard
61	          plans={plans.map((p) => ({
62	            id: p.id,
63	            name: p.name,
64	            cpuCores: p.cpuCores,
65	            ramMB: p.ramMB,
66	            diskGB: p.diskGB,
67	            bandwidthTB: p.bandwidthTB,
68	            priceCents: p.priceCents,
69	            storageTier: p.storageTier,
70	          }))}
71	          images={images.map((o) => ({
72	            id: o.id,
73	            slug: o.slug,
74	            name: o.name,
75	            category: o.category,
76	            family: o.family,
77	            version: o.version,
78	            logo: o.logo,
79	            minRamMB: o.minRamMB,
80	            minDiskGB: o.minDiskGB,
81	            licenseRequired: o.licenseRequired,
82	            featured: o.featured,
