18	export function ResizeDown({
19	  serverId,
20	  currentPlanId,
21	  currentDiskGB,
22	  currentPriceCents,
23	  termMonths,
24	  termPromoPercent,
25	  expiresAt,
26	  isFree,
27	  plans,
28	  disabled,
29	}: {
30	  serverId: string;
31	  currentPlanId: string;
32	  currentDiskGB: number;
33	  currentPriceCents: number;
34	  termMonths: number;
35	  /**
36	   * `Server.termPromoPercent` — the rate the remaining months were actually sold
37	   * at. Passed down verbatim (null included) so this display and
38	   * lib/actions-server-lifecycle.ts resolve the SAME basis.
39	   */
40	  termPromoPercent: number | null;
