47	  const [selected, setSelected] = useState<string | null>(null);
48	  const [error, setError] = useState<string | null>(null);
49	  const [pending, start] = useTransition();
50	
51	  // A downgrade candidate must be cheaper AND keep the disk at least as large.
52	  //
53	  // Filtering on price alone offered targets that could NEVER succeed: a disk
54	  // cannot shrink on the hypervisor, so `resizeServerDown` refuses any plan with a
55	  // smaller disk — and in the live catalogue every cheaper plan HAS a smaller disk
56	  // (Starter 25GB / Standard 50GB / Pro 80GB / Max 120GB), which makes the number
57	  // of viable downgrades exactly ZERO. Customers were shown a list of options and
58	  // every single one errored. The guard is correct; offering the action was the bug.
59	  const smaller = plans.filter(
60	    (p) => p.id !== currentPlanId && p.priceCents < currentPriceCents && p.diskGB >= currentDiskGB
61	  );
62	  // Cheaper plans that exist but are blocked purely by the disk rule — used to
63	  // explain WHY there is nothing to choose, instead of showing an empty box.
64	  const blockedByDisk = plans.filter(
65	    (p) => p.id !== currentPlanId && p.priceCents < currentPriceCents && p.diskGB < currentDiskGB
