131	          </p>
132	        )
133	      ) : (
134	        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
135	          {smaller.map((p) => {
136	            const diskShrinks = p.diskGB < currentDiskGB;
137	            const active = selected === p.id;
138	            return (
139	              <button
140	                key={p.id}
141	                type="button"
142	                disabled={diskShrinks || pending || disabled}
143	                title={
144	                  diskShrinks
145	                    ? `Disk can't shrink — this plan has ${p.diskGB} GB, your server uses a ${currentDiskGB} GB disk.`
146	                    : undefined
147	                }
148	                onClick={() => setSelected(active ? null : p.id)}
149	                className={`card p-4 text-left transition-all ${
