167	                {diskShrinks && (
168	                  <p className="mt-2 text-xs text-slate-500">Smaller disk — can&apos;t shrink</p>
169	                )}
170	              </button>
171	            );
172	          })}
173	        </div>
174	      )}
175	
176	      {smaller.length > 0 && (
177	        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
178	          <p className="text-xs text-slate-400">
179	            {target && credit > 0 ? (
180	              <>
181	                Estimated credit back to your wallet:{" "}
182	                <span className="font-semibold text-emerald-400">{fmtMoney(credit)}</span>. Requires a
183	                power cycle.
184	              </>
185	            ) : (
186	              "Downsizing requires a power cycle. The new price applies at your next renewal."
187	            )}
188	          </p>
189	          <button
190	            className="btn-primary"
191	            disabled={!target || pending || disabled}
192	            onClick={() => {
193	              if (!target) return;
194	              if (
195	                !window.confirm(
196	                  `Downsize this server to ${target.name} (${fmtMoney(target.priceCents)}/mo)?${
197	                    credit > 0 ? ` ${fmtMoney(credit)} will be credited to your wallet.` : ""
198	                  } The server will be power-cycled.`
