119	/* ------------------------------------------------------------------ *
120	 * The return leg from Stripe
121	 * ------------------------------------------------------------------ */
122	
123	type FinalizeState =
124	  | { kind: "working" }
125	  | { kind: "saved"; label: string }
126	  | { kind: "failed"; error: string };
127	
128	/**
129	 * Completes card setup after Stripe redirects back to
130	 * `/dashboard/billing?card_setup=<session_id>`.
131	 *
132	 * Two things this must not be:
133	 *  - a silent no-op. Checkout attaches the card at Stripe BEFORE this ever runs,
134	 *    so a customer who lands here and sees nothing has a card at Stripe and none
135	 *    on file with us — and would be dunned for it.
136	 *  - a dead end. If finalising fails, the card may still be saved at Stripe, and
137	 *    the worker's `adoptUnclaimedCards` backstop claims it on the next sweep. The
138	 *    failure copy says exactly that, and still offers a retry.
139	 *
140	 * `finalizeCardSetup` is documented as safe to call repeatedly with the same
141	 * session id, so a refreshed tab re-reads the same payment method rather than
142	 * saving a second card. The ref below is not for correctness, only to stop React's
143	 * development double-mount from firing two identical round-trips.
144	 */
145	export function CardSetupReturn({ sessionId }: { sessionId: string }) {
146	  const router = useRouter();
147	  const fired = useRef(false);
148	  const [state, setState] = useState<FinalizeState>({ kind: "working" });
149	  const canceled = sessionId === "canceled";
150	
151	  useEffect(() => {
152	    if (canceled || fired.current) return;
153	    fired.current = true;
154	    void (async () => {
155	      const res = await finalizeCardSetup(sessionId);
156	      if (res.ok) {
157	        setState({ kind: "saved", label: res.label ?? "Card saved" });
158	        // Drop the one-shot session id from the URL so a refresh or a shared link
159	        // doesn't replay the return leg, then pull the page's server data again —
160	        // the action has already revalidated it.
161	        router.replace("/dashboard/billing");
162	        router.refresh();
163	        return;
164	      }
165	      setState({ kind: "failed", error: res.error ?? "The card wasn't saved." });
166	    })();
167	  }, [sessionId, canceled, router]);
168	
169	  if (canceled) {
170	    return (
171	      <div className="card border-amber-500/30 bg-amber-500/[0.06]">
172	        <p className="text-sm font-medium text-amber-300">Card setup canceled</p>
173	        <p className="mt-1 text-sm text-slate-400">
174	          No card was saved and nothing was charged. Your renewals will keep coming out of your
175	          wallet balance until a card is on file.
176	        </p>
177	        <div className="mt-3">
178	          <AddCardButton label="Try again" className="btn-secondary py-1.5" />
179	        </div>
180	      </div>
181	    );
182	  }
183	
184	  if (state.kind === "working") {
185	    return (
186	      <div className="card border-white/[0.08] text-sm text-slate-400">
187	        Finishing card setup — one moment.
188	      </div>
189	    );
190	  }
191	
192	  if (state.kind === "saved") {
193	    return (
194	      <div className="card border-emerald-500/30 bg-emerald-500/[0.06]">
195	        <p className="text-sm font-medium text-emerald-300">{state.label} saved</p>
196	        <p className="mt-1 text-sm text-slate-400">
197	          Renewals will now charge this card for anything your wallet balance doesn&apos;t cover.
198	        </p>
199	      </div>
200	    );
201	  }
202	
203	  return (
204	    <div className="card border-red-500/30 bg-red-500/[0.06]">
205	      <p className="text-sm font-medium text-red-300">We couldn&apos;t finish saving your card</p>
206	      <p className="mt-1 text-sm text-slate-400">{state.error}</p>
207	      <p className="mt-2 text-xs text-slate-500">
208	        If you completed the form on Stripe&apos;s page, the card may already be saved on their side
209	        — we check for that automatically and it will appear here within a few minutes. Nothing was
210	        charged either way.
211	      </p>
212	      <div className="mt-3">
213	        <AddCardButton label="Try again" className="btn-secondary py-1.5" />
214	      </div>
215	    </div>
216	  );
217	}
