219	/* ------------------------------------------------------------------ *
220	 * Settle an outstanding balance
221	 * ------------------------------------------------------------------ */
222	
223	/**
224	 * Pay an overdue renewal now, on Stripe's hosted page.
225	 *
226	 * The link is minted fresh on every click rather than reusing the stored
227	 * `dunningPayUrl`, because Checkout sessions expire in 24 hours while the dunning
228	 * sequence runs for six days — see `settleOutstanding`.
229	 *
230	 * `covered: true` is NOT a failure: it means the wallet already funds the renewal
231	 * and the sweep will apply it. It gets neutral styling, not an error colour.
232	 */
233	export function SettleNowButton({
234	  serverId,
235	  className = "btn-primary py-1.5 text-xs",
236	}: {
237	  serverId: string;
238	  className?: string;
239	}) {
240	  const [message, setMessage] = useState<{ tone: "info" | "error"; text: string } | null>(null);
241	  const [pending, start] = useTransition();
242	
243	  const pay = () => {
244	    setMessage(null);
245	    start(async () => {
246	      const res = await settleOutstanding(serverId);
247	      if (res.url) {
248	        window.location.href = res.url;
249	        return;
250	      }
251	      setMessage({
252	        tone: res.covered ? "info" : "error",
253	        text: res.error ?? "We couldn't start checkout. Please try again in a moment.",
254	      });
255	    });
256	  };
257	
258	  return (
259	    <div>
260	      <button className={className} onClick={pay} disabled={pending}>
261	        {pending ? "Opening checkout…" : "Pay now"}
262	      </button>
263	      {message && (
264	        <p
265	          className={`mt-2 text-xs ${
266	            message.tone === "info" ? "text-slate-400" : "text-red-400"
267	          }`}
268	        >
269	          {message.text}
270	        </p>
271	      )}
272	    </div>
273	  );
274	}
