18	/**
19	 * Promo-code entry for the wallet top-up flow. On a valid code it stores the
20	 * code in a short-lived cookie which `topUp` reads and applies to the real
21	 * top-up amount (this keeps the existing AddFunds form untouched).
22	 *
23	 * The green "applied" state below is a promise, so it may only appear when the
24	 * bonus will really be credited. `applyCouponToTopup` now refuses outright
25	 * whenever no code path can honour the code (see `topupCouponRedeemable` in
26	 * `lib/actions-growth.ts`) — previously it returned ok, this rendered "Bonus is
27	 * credited when you add funds", and the card checkout then charged full price and
28	 * credited nothing. A refusal lands in the red error line instead, which is the
29	 * honest outcome: a disabled control the customer can see beats an enabled one
30	 * that lies.
31	 */
32	export function CouponField() {
33	  const [code, setCode] = useState("");
34	  const [applied, setApplied] = useState<{ code: string; label: string } | null>(null);
35	  const [error, setError] = useState<string | null>(null);
36	  const [pending, start] = useTransition();
37	
38	  const apply = () => {
39	    setError(null);
40	    const trimmed = code.trim();
41	    if (!trimmed) {
42	      setError("Enter a promo code.");
43	      return;
44	    }
45	    start(async () => {
46	      const res: CouponApplyResult = await applyCouponToTopup(trimmed, PREVIEW_CENTS);
47	      if (res.ok) {
48	        setCookie(res.code);
49	        setApplied({ code: res.code, label: res.label });
50	        setError(null);
51	      } else {
52	        clearCookie();
53	        setApplied(null);
54	        setError(res.error);
55	      }
56	    });
57	  };
58	
59	  const remove = () => {
60	    clearCookie();
61	    setApplied(null);
62	    setCode("");
63	    setError(null);
64	  };
65	
66	  if (applied) {
67	    return (
68	      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-emerald-500/30 bg-emerald-500/[0.06] px-3 py-2 text-sm">
